#!/usr/bin/env node
/**
 * Warranty Claim Logger — Saves detailed claim and order info to a structured log file.
 */

const fs = require("fs");
const path = require("path");

const LOG_FILE = path.join(__dirname, "warranty_claims.json");

// ---------------------------------------------------------------------------
// Persistence helpers
// ---------------------------------------------------------------------------

function loadClaims() {
  if (fs.existsSync(LOG_FILE)) {
    return JSON.parse(fs.readFileSync(LOG_FILE, "utf-8"));
  }
  return [];
}

function saveClaims(claims) {
  fs.writeFileSync(LOG_FILE, JSON.stringify(claims, null, 2));
}

// ---------------------------------------------------------------------------
// Core: log a new claim
// ---------------------------------------------------------------------------

function logClaim({ order, item, warranty, issue }) {
  const claims = loadClaims();

  const claim = {
    claim_number: claims.length + 1,
    date_filed: new Date().toISOString(),

    order: {
      order_id: order.orderId,
      order_date: order.orderDate,
      order_status: order.orderStatus,
      customer: {
        name: order.customer.name,
        email: order.customer.email,
        phone: order.customer.phone,
        address: order.customer.address,
      },
      payment: {
        method: order.payment.method,
        total: order.payment.total,
        currency: order.payment.currency,
      },
    },

    item: {
      item_id: item.itemId,
      item_name: item.itemName,
      category: item.category,
      quantity: item.quantity,
      unit_price: item.unitPrice,
      currency: item.currency,
    },

    warranty: {
      warranty_id: warranty.warrantyId,
      type: warranty.type,
      start_date: warranty.startDate,
      end_date: warranty.endDate,
      provider: warranty.provider,
    },

    issue: {
      type: issue.type,
      description: issue.description,
      date_noticed: issue.dateNoticed,
    },

    status: "Pending",
  };

  claims.push(claim);
  saveClaims(claims);
  return claim;
}

// ---------------------------------------------------------------------------
// Pretty-print a claim
// ---------------------------------------------------------------------------

function printClaimSummary(claim) {
  const W = 58;
  const sep = "=".repeat(W);
  const dash = "-".repeat(W);

  const pad = (label, value) =>
    `  ${label.padEnd(20)} ${value}`;

  console.log(sep);
  console.log("          WARRANTY CLAIM RECORD");
  console.log(sep);
  console.log(pad("Claim #:", String(claim.claim_number)));
  console.log(pad("Date Filed:", claim.date_filed));

  console.log(dash);
  console.log("  ORDER INFORMATION");
  console.log(pad("Order ID:", claim.order.order_id));
  console.log(pad("Order Date:", claim.order.order_date));
  console.log(pad("Order Status:", claim.order.order_status));
  console.log(pad("Payment:", `${claim.order.payment.method} — ${claim.order.payment.currency} ${claim.order.payment.total}`));

  console.log(dash);
  console.log("  CUSTOMER");
  console.log(pad("Name:", claim.order.customer.name));
  console.log(pad("Email:", claim.order.customer.email));
  console.log(pad("Phone:", claim.order.customer.phone));
  console.log(pad("Address:", claim.order.customer.address));

  console.log(dash);
  console.log("  ITEM DETAILS");
  console.log(pad("Item ID:", claim.item.item_id));
  console.log(pad("Item Name:", claim.item.item_name));
  console.log(pad("Category:", claim.item.category));
  console.log(pad("Quantity:", String(claim.item.quantity)));
  console.log(pad("Unit Price:", `${claim.item.currency} ${claim.item.unit_price}`));

  console.log(dash);
  console.log("  WARRANTY DETAILS");
  console.log(pad("Warranty ID:", claim.warranty.warranty_id));
  console.log(pad("Type:", claim.warranty.type));
  console.log(pad("Provider:", claim.warranty.provider));
  console.log(pad("Coverage Period:", `${claim.warranty.start_date} → ${claim.warranty.end_date}`));

  console.log(dash);
  console.log("  ISSUE DETAILS");
  console.log(pad("Issue Type:", claim.issue.type));
  console.log(pad("Date Noticed:", claim.issue.date_noticed));
  console.log(pad("Description:", claim.issue.description));

  console.log(dash);
  console.log(pad("Claim Status:", claim.status));
  console.log(sep);
}

